package com.web2app.nativeplugin

import android.app.Activity
import android.graphics.Color
import android.webkit.WebView
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Plugin

/** Mirrors `plugins.web2app-native` in tauri.conf.json (generated by scripts/sync-config.sh). */
@InvokeArg
class NativeConfig {
    var downloads: Boolean = true
    var statusBarColor: String? = null
    var navigationBarColor: String? = null
}

/**
 * Web2App native helper plugin. It exposes NO commands to web content: it only
 * attaches native behaviour to the Tauri WebView when the plugin is loaded.
 */
@TauriPlugin
class NativePlugin(private val activity: Activity) : Plugin(activity) {
    override fun load(webView: WebView) {
        super.load(webView)
        val config = try {
            getConfig(NativeConfig::class.java)
        } catch (e: Exception) {
            NativeConfig()
        }
        if (config.downloads) {
            DownloadHandler(activity).attach(webView)
        }
        applySystemBarColors(config)
    }

    /**
     * Best effort: Android 15+ enforces edge-to-edge and ignores these colors
     * (documented as Platform Limited). Invalid colors are ignored.
     */
    @Suppress("DEPRECATION")
    private fun applySystemBarColors(config: NativeConfig) {
        activity.runOnUiThread {
            try {
                config.statusBarColor?.let { activity.window.statusBarColor = Color.parseColor(it) }
                config.navigationBarColor?.let { activity.window.navigationBarColor = Color.parseColor(it) }
            } catch (e: Exception) {
                // ignore: purely cosmetic
            }
        }
    }
}
